#include <stdio.h>

int main() {
    long long n;
    if (scanf("%lld", &n) == 1) {
        if (n == 0) { printf("0\n"); return 0; }
        char bin[65];
        int idx = 0;
        while (n > 0) {
            bin[idx++] = (n % 2) + '0';
            n /= 2;
        }
        for (int i = idx - 1; i >= 0; i--) putchar(bin[i]);
        putchar('\n');
    }
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    if (cin >> n) {
        if (n == 0) { cout << "0\n"; return 0; }
        string s = "";
        while (n > 0) {
            s += (n % 2 ? '1' : '0');
            n /= 2;
        }
        reverse(s.begin(), s.end());
        cout << s << "\n";
    }
    return 0;
}

